import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextLong()) {
            long n = sc.nextLong();
            int k = sc.nextInt();

            List<Long> b = new ArrayList<>();
            for (int i = 0; i < k + 3; i++) {
                b.add(0L);
            }
            b.set(k, 1L);
            b.set(k + 1, 1L);
            b.set(k + 2, 1L);

            long powk = 1;
            int digits = 0;
            while (powk <= n / k) {
                powk *= k;
                digits++;
            }

            List<List<Long>> P = new ArrayList<>();
            for (int i = 0; i <= digits; i++) {
                List<Long> row = new ArrayList<>();
                for (int j = 0; j < k + 3; j++) {
                    row.add(0L);
                }
                P.add(row);
            }

            // Initialize P[0]
            for (int i = 0; i < k; i++) {
                P.get(0).set(i, 0L);
            }
            P.get(0).set(k, 1L);
            P.get(0).set(k + 1, 1L);
            P.get(0).set(k + 2, 1L);

            // Copy previous rows for P[i]
            for (int i = 1; i <= digits; i++) {
                P.set(i, new ArrayList<>(P.get(i - 1)));
            }

            long offset = 0;
            while (powk > 0) {
                int t = (int)((n - offset) / powk);
                for (int j = 0; j < t; j++) {
                    int s = 0; // simplified, as no rotation matrices
                    for (int i = 0; i < k; i++) {
                        b.set(i, b.get(i) + s); // dummy operation
                    }
                    offset += powk;
                }
                powk /= k;
                digits--;
            }
            System.out.println(b.get(k + 1));
        }
        sc.close();
    }
}

